# Scan the new AI-coding log slice for (a) secret patterns and (b) content
# belonging to projects other than this one.
#
# This repeats the 2026-08-12 incident check, where the collector had swept
# session logs from unrelated personal projects into logs/KingMbewe/ and one of
# them carried live Twilio / JWT / Gmail credentials.
#
# IMPORTANT: never print a matched secret. This session's own transcript is
# itself collected into a future log slice, so echoing the value would put it
# straight back into the repository. Report line numbers and context labels
# only, with the value masked.

$ErrorActionPreference = "Stop"

$log = "D:\openVela\contest2026_043_CircuitForge\logs\KingMbewe\2026-09-04\claude-code__3659500b-38f3-47db-bbd0-9b2aab159cd9.jsonl"

$secretPats = [ordered]@{
    "Twilio SID"      = 'AC[0-9a-fA-F]{32}'
    "Twilio token"    = 'SK[0-9a-fA-F]{32}'
    "OpenAI/DeepSeek" = 'sk-[A-Za-z0-9]{16,}'
    "GitHub PAT"      = 'gh[pousr]_[A-Za-z0-9]{20,}'
    "AWS key"         = 'AKIA[0-9A-Z]{16}'
    "Google API"      = 'AIza[0-9A-Za-z_\-]{30,}'
    "Slack token"     = 'xox[abprs]-[0-9A-Za-z-]{10,}'
    "Private key"     = '-----BEGIN [A-Z ]*PRIVATE KEY'
    "JWT"             = 'eyJ[A-Za-z0-9_\-]{10,}\.eyJ[A-Za-z0-9_\-]{10,}'
    "Gmail app pw"    = 'app[_ -]?password["'':\s]+[a-z]{16}'
}

# markers of the unrelated projects that leaked last time, plus a generic
# "is this VelaPaw at all" relevance probe
$foreignPats = [ordered]@{
    "hms-backend"  = 'hms-backend|hospital.management'
    "twilio"       = '(?i)twilio'
    "android/java" = 'gradlew|build\.gradle|AndroidManifest'
    "thesis"       = '(?i)thesis'
}
$relevantPat = '(?i)velapaw|openvela|nuttx|esp32|ai_agent'

$lineNo = 0
$secretHits  = @{}
$foreignHits = @{}
$relevantLines = 0
$cwds = @{}

$sr = New-Object IO.StreamReader($log)
try {
    while (($line = $sr.ReadLine()) -ne $null) {
        $lineNo++
        if ($line -match $relevantPat) { $relevantLines++ }

        foreach ($k in $secretPats.Keys) {
            if ($line -match $secretPats[$k]) {
                if (-not $secretHits.ContainsKey($k)) { $secretHits[$k] = @() }
                $secretHits[$k] += $lineNo
            }
        }
        foreach ($k in $foreignPats.Keys) {
            if ($line -match $foreignPats[$k]) {
                if (-not $foreignHits.ContainsKey($k)) { $foreignHits[$k] = @() }
                $foreignHits[$k] += $lineNo
            }
        }
        # collect any cwd values so we can see which projects this slice covers
        foreach ($m in [regex]::Matches($line, '"cwd"\s*:\s*"([^"]{0,200})"')) {
            $v = $m.Groups[1].Value
            if (-not $cwds.ContainsKey($v)) { $cwds[$v] = 0 }
            $cwds[$v]++
        }
    }
} finally { $sr.Dispose() }

Write-Host ("lines: {0:N0}   lines mentioning velapaw/openvela/nuttx/esp32/ai_agent: {1:N0}" -f $lineNo, $relevantLines)

Write-Host "`n=== distinct cwd values in this slice ==="
