$cwds.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 15 |
    ForEach-Object { Write-Host ("  {0,7:N0}  {1}" -f $_.Value, $_.Key) }

Write-Host "`n=== secret-pattern hits (values masked) ==="
if ($secretHits.Count -eq 0) { Write-Host "  none" }
foreach ($k in $secretHits.Keys) {
    $v = $secretHits[$k]
    Write-Host ("  {0,-16} {1} line(s): {2}" -f $k, $v.Count, (($v | Select-Object -First 12) -join ", "))
}

Write-Host "`n=== foreign-project markers ==="
if ($foreignHits.Count -eq 0) { Write-Host "  none" }
foreach ($k in $foreignHits.Keys) {
    $v = $foreignHits[$k]
    Write-Host ("  {0,-16} {1} line(s): {2}" -f $k, $v.Count, (($v | Select-Object -First 12) -join ", "))
}

# Show WHAT the flagged lines are, with every secret-shaped token masked before
