function Mask([string]$s) {
    $s = $s -replace 'AC[0-9a-fA-F]{32}',       'AC<<TWILIO-SID-MASKED>>'
    $s = $s -replace 'SK[0-9a-fA-F]{32}',       'SK<<MASKED>>'
    $s = $s -replace 'sk-[A-Za-z0-9]{16,}',     'sk-<<MASKED>>'
    $s = $s -replace '[0-9a-fA-F]{32}',         '<<HEX32-MASKED>>'
    $s = $s -replace 'eyJ[A-Za-z0-9_\-]{10,}\.eyJ[A-Za-z0-9_\-]{10,}[A-Za-z0-9_.\-]*', '<<JWT-MASKED>>'
    return $s
}

