# Classify the flagged records WITHOUT printing their text.
#
# Output is metadata only (role / timestamp / seq) plus which keywords from a
# fixed vocabulary the record matched. No free text from the log is echoed, so
# neither the credential nor any unrelated project's content can leak into this
# session's transcript (which itself becomes a future log slice).

$ErrorActionPreference = "Stop"
$log = "D:\openVela\contest2026_043_CircuitForge\logs\KingMbewe\2026-09-04\claude-code__3659500b-38f3-47db-bbd0-9b2aab159cd9.jsonl"

$vocab = [ordered]@{
    "velapaw"   = '(?i)velapaw'
    "openvela"  = '(?i)openvela|nuttx|esp32'
    "twilio"    = '(?i)twilio'
    "hms"       = '(?i)hms-backend|hospital'
    "thesis"    = '(?i)thesis'
    "sid-shape" = 'AC[0-9a-fA-F]{32}'
    "env-file"  = '(?i)\.env|environment variable'
    "memory"    = '(?i)memory|MEMORY\.md'
    "incident"  = '(?i)push protection|GH013|secret scanning|leak'
}

$lineNo = 0
$rows = @()
$sr = New-Object IO.StreamReader($log)
try {
    while (($line = $sr.ReadLine()) -ne $null) {
        $lineNo++
        $isHit = ($line -match 'AC[0-9a-fA-F]{32}') -or ($line -match '(?i)twilio') -or ($line -match '(?i)hms-backend|hospital')
        if (-not $isHit) { continue }

        $tags = @()
        foreach ($k in $vocab.Keys) { if ($line -match $vocab[$k]) { $tags += $k } }

        $role = ""; $ts = ""; $seq = ""
        if ($line -match '"role"\s*:\s*"([a-z]+)"')  { $role = $Matches[1] }
        if ($line -match '"ts"\s*:\s*"([^"]+)"')     { $ts   = $Matches[1] }
        if ($line -match '"seq"\s*:\s*(\d+)')        { $seq  = $Matches[1] }

        $rows += [pscustomobject]@{
            Line = $lineNo; Role = $role; Seq = $seq; Ts = $ts
            Chars = $line.Length; Tags = ($tags -join ",")
        }
    }
} finally { $sr.Dispose() }

Write-Host ("flagged records: {0}" -f $rows.Count)
Write-Host ""
$rows | Format-Table -AutoSize Line, Role, Seq, Ts, Chars, Tags | Out-String -Width 200 | Write-Host

Write-Host "=== how many flagged records ALSO mention velapaw/openvela ==="
$both = @($rows | Where-Object { $_.Tags -match 'velapaw|openvela' })
Write-Host ("  {0} of {1}" -f $both.Count, $rows.Count)

